CREATE OR REPLACE FUNCTION calculate_avg_engagement(p_client_id INT) RETURNS NUMERIC AS $$
BEGIN
    RETURN (
        SELECT COALESCE(AVG(engagement_score), 0.00) AS avg_score
        FROM therapy_sessions AS t
        WHERE t.session_date > now()::date - INTERVAL '90 days' 
        AND t.client_id = p_client_id
    );
END;
$$ LANGUAGE PLPGSQL;


SELECT calculate_avg_engagement(1) AS avg_score;
